// ═══ Detect Category từ keyword để load đúng FewShots ═══
const body = $input.first().json.body || $input.first().json || {};
let rawMsg = body.message || body.text || '';

// Tiền xử lý dọn dẹp tiếng Việt nói lủng củng: biến liên từ thành dấu phẩy để giảm tải cho LLM
rawMsg = rawMsg.replace(/\s+(và|cùng với|đi kèm|với|&)\s+/gi, ', ');
rawMsg = rawMsg.replace(/\s+/g, ' ').trim();

const message = rawMsg.toLowerCase();
const historyContext = body.historyContext || '';
const sessionId = body.sessionId || 'default';

// Keyword map để đoán category TRƯỚC khi gọi LLM
// → load đúng few-shots, giảm token 40-60%
const CATEGORY_KEYWORDS = {
  SALES:    ['doanh', 'dt ', 'dts', 'hóa đơn', 'đơn hàng', 'top nv', 'top kh', 'bán được', 'lên đơn', 'giỏ hàng', 'đặt hàng'],
  CUSTOMER: ['khách', 'kh ', 'nợ', 'công nợ', 'vip', 'nhóm', 'tích lũy', 'hạng', 'ghé', 'tuyến', 'lâu chưa mua', 'chấm điểm', 'tín nhiệm', 'khảo sát'],
  PRODUCT:  ['thuốc', 'sp ', 'sản phẩm', 'tồn kho', 'còn hàng', 'gợi ý', 'ho ', 'cảm ', 'đau', 'bệnh', 'trọng tâm', 'date', 'xả hàng', 'tìm', 'loại', 'khuyến mãi', 'danh mục'],
};

let category = 'GENERAL';
for (const [cat, keywords] of Object.entries(CATEGORY_KEYWORDS)) {
  if (keywords.some(kw => message.includes(kw))) {
    category = cat;
    break;
  }
}

// Load few-shots theo category (hardcode để đảm bảo hoạt động)
const FEWSHOTS = {
  SALES: [
    'Input: "doanh thu tháng này" → {"intent":"@doanh_so","params":{"@TuNgay":"[THIS_MONTH_START]","@DenNgay":"[TODAY]"},"status":"SUCCESS","category":"SALES"}',
    'Input: "top nv bán nhiều nhất năm nay" → {"intent":"@doanh_so","params":{"@TuNgay":"[THIS_YEAR_START]","@DenNgay":"[TODAY]","@LoaiBaoCao":"NhanVien"},"status":"SUCCESS","category":"SALES"}',
    'Input: "lên đơn cho anh Hùng 10 abc, 5 xyz" → {"intent":"@lap_don_hang","action":"ADD","items":[{"keyword":"abc","qty":10},{"keyword":"xyz","qty":5}],"params":{"@MaKhachHang":"hùng"},"status":"SUCCESS","category":"SALES"}',
    'Input: "Lên đơn 5 hộp Antrinano cho Thu Thủy" → {"intent":"@lap_don_hang","action":"ADD","items":[{"keyword":"Antrinano","qty":5}],"params":{"@MaKhachHang":"Thu Thủy"},"status":"SUCCESS","category":"SALES"}',
    'Input: "Lên đơn 5 hộp Topalpha cho Nhà Thuốc Lê Hùng 2" → {"intent":"@lap_don_hang","action":"ADD","items":[{"keyword":"Topalpha","qty":5}],"params":{"@MaKhachHang":"Nhà Thuốc Lê Hùng 2"},"status":"SUCCESS","category":"SALES"}',
    'Input: "Tìm hóa đơn gần đây của Quầy Thuốc Thu Thủy" → {"intent":"@hoa_don","params":{"@MaKhachHang":"Quầy Thuốc Thu Thủy"},"status":"SUCCESS","category":"SALES"}',
    'Input: "Kiểm tra đơn hàng gần đây của tôi" → {"intent":"@don_hang","params":{},"status":"SUCCESS","category":"SALES"}',
  ],
  CUSTOMER: [
    'Input: "HK001 thuộc nhóm nào" → {"intent":"@cham_diem_kh","params":{"@MaKhachHang":"HK001"},"status":"SUCCESS","category":"CUSTOMER"}',
    'Input: "nó nợ bao nhiêu" (no history) → {"intent":"@cong_no_chi_tiet","params":{},"status":"ASK_CLARIFICATION","missing_fields":["@MaKhachHang"],"category":"CUSTOMER"}',
    'Input: [History: KH001] "mua nhiều vậy lên hạng chưa" → {"intent":"@cham_diem_kh","params":{"@MaKhachHang":"KH001"},"status":"SUCCESS","category":"CUSTOMER"}',
    'Input: "Chi tiết hóa đơn chưa thanh toán của Quầy Thuốc Thu Thủy" → {"intent":"@cong_no_chi_tiet","params":{"@MaKhachHang":"Quầy Thuốc Thu Thủy"},"status":"SUCCESS","category":"CUSTOMER"}',
    'Input: "Hôm nay tôi cần đi thăm những nhà thuốc nào?" → {"intent":"@tuyen_ban_hang","params":{},"status":"SUCCESS","category":"CUSTOMER"}',
    'Input: "Xem điểm tích lũy của Quầy Thuốc Thu Thủy" → {"intent":"@tich_luy","params":{"@MaKhachHang":"Quầy Thuốc Thu Thủy"},"status":"SUCCESS","category":"CUSTOMER"}',
    'Input: "Chấm điểm tín nhiệm nhà thuốc Thu Thủy" → {"intent":"@cham_diem_kh","params":{"@MaKhachHang":"Thu Thủy"},"status":"SUCCESS","category":"CUSTOMER"}',
    'Input: "Bắt đầu bài khảo sát cho Quầy Thuốc Thu Thủy" → {"intent":"@danh_sach_cau_hoi_khao_sat","params":{"@MaKhachHang":"Quầy Thuốc Thu Thủy"},"status":"SUCCESS","category":"CUSTOMER"}',
    'Input: "Tổng công nợ vùng tôi tháng 5" → {"intent":"@cong_no_khach_hang","params":{},"status":"SUCCESS","category":"CUSTOMER"}',
  ],
  PRODUCT: [
    'Input: "khách bị ho nên bán gì" → {"intent":"@upsell_goi_y","params":{"@timkiem":"ho"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "còn bao nhiêu hộp vitamin C" → {"intent":"@danh_sach_tonkho","params":{"@timkiem":"vitamin C"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Tôi cần tìm các loại thuốc Aquamed bổ sung sức đề kháng cho bé." → {"intent":"@upsell_goi_y","params":{"@timkiem":"Aquamed"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Gợi ý cho tôi 3 mặt hàng thường xuyên được bán kèm cùng với Ăn ngủ ngon." → {"intent":"@upsell_goi_y","params":{"@timkiem":"Ăn ngủ ngon"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Gợi ý thuốc thay thế bổ trợ khi bán Amoxicillin và Vitamin C" → {"intent":"@goi_ydon_thuoc","params":{"@timkiem":"Amoxicillin, Vitamin C"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Gợi ý đơn hàng cho Quầy Thuốc Thu Thủy" → {"intent":"@goi_ydon_hang","params":{"@MaKhachHang":"Quầy Thuốc Thu Thủy"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Có sản phẩm nào bán kèm Antrinano không?" → {"intent":"@upsell_goi_y","params":{"@timkiem":"Antrinano"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Thông tin chi tiết sản phẩm Argelomag" → {"intent":"@tra_cuu_san_pham","params":{"@timkiem":"Argelomag"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Khuyến mãi mới nhất đang chạy là gì?" → {"intent":"@de_xuat_khuyen_mai","params":{},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Các sản phẩm trọng tâm tháng này là gì?" → {"intent":"@san_pham_trong_tam","params":{},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Xem danh mục phân loại sản phẩm công ty" → {"intent":"@danh_muc","params":{},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Kiểm tra tồn kho sản phẩm Antrinano" → {"intent":"@danh_sach_tonkho","params":{"@timkiem":"Antrinano"},"status":"SUCCESS","category":"PRODUCT"}',
    'Input: "Mất ngủ, mệt mỏi thì uống thuốc gì?" → {"intent":"@goi_ydon_thuoc","params":{"@timkiem":"mất ngủ, mệt mỏi"},"status":"SUCCESS","category":"PRODUCT"}',
  ],
  GENERAL: [
    'Input: "xem giúp anh" → {"intent":null,"params":{},"status":"ASK_CLARIFICATION","missing_fields":["intent"],"category":"GENERAL"}',
  ]
};

const fewShotStr = (FEWSHOTS[category] || FEWSHOTS.GENERAL).join('\n');

return [{ json: { message, historyContext, sessionId, category, fewShotStr, originalBody: body } }];

const llmRaw = $input.first().json.output || $input.first().json.text || '';
const category = $('Detect Category & Load FewShots').first().json.category;

let result = { intent: null, params: {}, status: 'ASK_CLARIFICATION', missing_fields: ['json_parse_error'], category };
try {
  const m = llmRaw.match(/{[\s\S]*}/);
  if (m) result = { ...JSON.parse(m[0]), category: JSON.parse(m[0]).category || category };
} catch(e) {}

// Normalize: ensure intent starts with @
if (result.intent && !result.intent.startsWith('@')) result.intent = '@' + result.intent;

// Date placeholder resolution
const now = new Date();
const pad = n => String(n).padStart(2,'0');
const toISO = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;

const getMonday = d => {
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1);
  return new Date(d.getFullYear(), d.getMonth(), diff);
};

const mondayThisWeek = getMonday(new Date());
const mondayLastWeek = new Date(mondayThisWeek.getTime() - 7 * 24 * 60 * 60 * 1000);
const sundayLastWeek = new Date(mondayThisWeek.getTime() - 24 * 60 * 60 * 1000);

const yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const dayBeforeYesterday = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000);

const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);

const qMonth = Math.floor(now.getMonth() / 3) * 3;
const thisQuarterStart = new Date(now.getFullYear(), qMonth, 1);
const lastQuarterStart = new Date(now.getFullYear(), qMonth - 3, 1);
const lastQuarterEnd = new Date(now.getFullYear(), qMonth, 0);

const placeholders = {
  '[TODAY]':                  toISO(now),
  '[YESTERDAY]':              toISO(yesterday),
  '[DAY_BEFORE_YESTERDAY]':   toISO(dayBeforeYesterday),
  '[THIS_WEEK_START]':        toISO(mondayThisWeek),
  '[LAST_WEEK_START]':        toISO(mondayLastWeek),
  '[LAST_WEEK_END]':          toISO(sundayLastWeek),
  '[THIS_MONTH_START]':       `${now.getFullYear()}-${pad(now.getMonth()+1)}-01`,
  '[THIS_YEAR_START]':        `${now.getFullYear()}-01-01`,
  '[LAST_MONTH_START]':       toISO(lastMonthStart),
  '[LAST_MONTH_END]':         toISO(lastMonthEnd),
  '[LAST_YEAR_START]':        `${now.getFullYear()-1}-01-01`,
  '[LAST_YEAR_END]':          `${now.getFullYear()-1}-12-31`,
  '[THIS_QUARTER_START]':     toISO(thisQuarterStart),
  '[LAST_QUARTER_START]':     toISO(lastQuarterStart),
  '[LAST_QUARTER_END]':       toISO(lastQuarterEnd),
};

if (!result.params) result.params = {};

// Clean up: resolve placeholders first
for (const k of Object.keys(result.params)) {
  if (placeholders[result.params[k]]) {
    result.params[k] = placeholders[result.params[k]];
  }
}

// Global MED ID Redirector: If ANY parameter contains an ID starting with 'MED' (e.g. MED0650 or MED0375), redirect it to @EmployeeID!
for (const k of Object.keys(result.params)) {
  const val = result.params[k];
  if (typeof val === 'string') {
    const medMatch = val.match(/\b(MED\d+)\b/i);
    if (medMatch) {
      const medId = medMatch[1].toUpperCase();
      result.params['@EmployeeID'] = medId;
      if (k !== '@EmployeeID') {
        delete result.params[k];
      }
    }
  }
}

// Clean up TenNhanVien: remove common prefixes like "nhân viên", "nhan vien", "nv", "của"
if (result.params['@TenNhanVien']) {
  let ten = String(result.params['@TenNhanVien']);
  ten = ten.replace(/^(nhân viên|nhan vien|nv|của|\s)+/gi, '').trim();
  result.params['@TenNhanVien'] = ten;
}

// Bracket parsing as a robust fallback for other entity IDs
for (const k of Object.keys(result.params)) {
  const val = result.params[k];
  if (typeof val === 'string' && (val.includes('[') || val.includes('('))) {
    const match = val.match(/[\{\[\(](.*?)[\}\]\)]/);
    if (match) {
      const id = match[1].trim();
      const fullStr = val.toLowerCase();
      if (fullStr.includes('nhân viên') || fullStr.includes(' nv ') || fullStr.startsWith('nv ') || k === '@TenNhanVien' || k === 'TenNhanVien' || k === '@EmployeeID' || k === 'EmployeeID') {
          result.params['@EmployeeID'] = id;
          if (k !== '@EmployeeID') delete result.params[k];
      } else if (fullStr.includes('khách hàng') || fullStr.includes(' kh ') || fullStr.startsWith('kh ') || k === '@ObjectName' || k === 'ObjectName' || k === '@TenKhachHang' || k === 'TenKhachHang' || k === '@MaKhachHang' || k === 'MaKhachHang') {
          result.params['@MaKhachHang'] = id;
          if (k !== '@MaKhachHang') delete result.params[k];
      } else if (fullStr.includes('sản phẩm') || fullStr.includes('thuốc') || fullStr.includes(' sp ') || fullStr.startsWith('sp ') || k === '@TenSanPham' || k === 'TenSanPham' || k === '@ItemID' || k === 'ItemID') {
          result.params['@ItemID'] = id;
          if (k !== '@ItemID') delete result.params[k];
      } else {
          result.params[k] = id;
      }
    }
  }
}

return [{ json: result }];
